"애플리케이션을 선택하거나 전체 경로를 입력하세요.":"Choose an application or enter its full path",
"설치된 ZCode 애플리케이션을 선택한 다음 연결 방법을 선택하고 관리 페이지에서 활성화하세요.":"Choose the installed ZCode application, then select a connection method and enable it on its management page.",
"ZCode는 이미 사용 가능합니다. 기존 관리 페이지를 사용하세요.":"ZCode is already available. Use its existing management page.",
