"ZCode는 아직 이 시스템에서 지원되지 않습니다.":"ZCode is not supported on this system yet.",
"ZCode 애플리케이션의 전체 경로를 선택하십시오.":"Select the full path to the ZCode application.",
"로컬 ZCode 애플리케이션의 전체 경로를 선택하십시오.":"Select the full path to a local ZCode application.",
"선택한 경로는 유효한 ZCode 애플리케이션이 아닙니다.":"The selected path is not a valid ZCode application.",
"ZCode에는 여전히 활성 연결이 있습니다. 다시 시도하기 전에 액세스를 비활성화하고 정상적으로 종료하십시오.":"ZCode still has an active connection. Disable access and quit it normally before retrying.",
"ZCode에는 여전히 활성 연결이 있습니다. 다시 시도하기 전에 액세스를 비활성화하세요.":"ZCode still has an active connection. Disable access before retrying.",
"클라이언트 구성 요청이 잘못되었습니다.":"Invalid client configuration request.",
"연결 이름":"Connection name",
"Codex 구성 디렉터리":"Codex configuration directory",
"WSL 분포":"WSL distribution",
"Linux 사용자":"Linux user",
"Linux 구성 디렉터리":"Linux configuration directory",
"실행 중인 WSL 배포, Linux 사용자 및 기존 구성 디렉터리를 입력합니다. 저장하면 디렉터리만 확인됩니다. 배포가 중지된 것으로 감지되면 먼저 배포를 시작하라는 메시지가 표시됩니다.":"Enter a running WSL distribution, Linux user, and existing configuration directory. Saving only verifies the directory. If the distribution is detected as stopped, you will be asked to start it first.",
