"WSL 클라이언트 등록 요청이 잘못되었습니다.":"Invalid WSL client registration request.",
"WSL 배포가 중지되었거나 사용할 수 없습니다. 컴퓨터에서 시작한 다음 다시 연결하세요.":"The WSL distribution is stopped or unavailable. Start it on your computer, then reconnect.",
