"이 클라이언트 구성을 삭제하시겠습니까? 해당 애플리케이션, 계정, 채팅 및 구성 파일은 보존됩니다.":"Remove this client configuration? Its application, accounts, chats and configuration files will be preserved.",
"클라이언트 구성이 제거됨":"Client configuration removed",
"구성을 제거하기 전에 이 클라이언트에 대한 모바일 액세스를 비활성화하십시오.":"Disable mobile access for this client before removing its configuration.",
"이 클라이언트 구성 제거를 확인하세요.":"Confirm removal of this client configuration.",
