"게이트웨이 연결":"Gateway connection",
"기본적으로 꺼져 있습니다. 선택한 어댑터의 IP 변경 사항을 따르고 실패한 임시 HTTPS 연결을 복구합니다. 변경 사항은 즉시 저장됩니다. 다시 시작할 필요가 없습니다.":"Off by default. Follow IP changes on selected adapters and recover failed temporary HTTPS connections. Changes are saved immediately; no restart needed.",
