"Claude가 종료되지 않았습니다. 작업을 처리하거나 컴퓨터에 프롬프트를 저장한 후 다시 시도하세요.":"Claude has not quit. Handle any task or save prompt on your computer, then try again.",
"Claude 종료 요청이 취소되었습니다.":"Claude quit request cancelled.",
"Claude의 네이티브 종료 메뉴를 찾을 수 없습니다. 컴퓨터에서 메뉴를 확인하고 다시 시도하세요.":"Claude's native Exit menu could not be found. Check its menu on your computer and try again.",
"둘 이상의 Claude 종료 메뉴가 발견되었습니다. 컴퓨터를 확인하고 다시 시도하세요.":"More than one Claude Exit menu was found. Check on your computer and try again.",
"Claude 기본 프로세스가 변경되었습니다. 종료 요청이 중지되었습니다.":"The Claude main process has changed. The quit request was stopped.",
"초점이 Claude에서 멀어졌습니다. 종료 요청이 중지되었습니다. 다시 시도해 보세요.":"Focus moved away from Claude. The quit request was stopped; try again.",
"Claude에는 보류 중인 네이티브 대화 상자가 있습니다. 컴퓨터에서 확인하거나 취소하세요.":"Claude has a pending native dialog. Confirm or cancel it on your computer.",
"Claude가 정상적으로 종료됩니다.":"Claude quit normally.",
"Claude가 컴퓨터에서 종료 확인을 기다리고 있습니다. 직접 확인하거나 취소하세요.":"Claude is waiting for quit confirmation on your computer. Confirm or cancel it yourself.",
"정상적인 Claude 종료가 요청되었습니다. 저장 및 종료가 완료되기를 기다리는 중입니다.":"A normal Claude quit was requested. Waiting for saving and shutdown to finish.",
"Claude 네이티브 종료 구성요소가 누락되었습니다. 게이트웨이 앱을 다시 빌드하거나 다시 설치하세요.":"The Claude native quit component is missing. Rebuild or reinstall the gateway app.",
"Claude 네이티브 종료 구성요소를 시작할 수 없습니다. 게이트웨이 설치를 확인하세요.":"The Claude native quit component could not start. Check the gateway installation.",
"Claude 네이티브 종료 요청 시간이 초과되었습니다. 컴퓨터에서 종료 상태를 확인하세요.":"The Claude native quit request timed out. Check its exit status on your computer.",
"Claude 네이티브 종료 구성 요소가 유효한 상태를 반환하지 않았습니다. 컴퓨터에서 종료 상태를 확인하세요.":"The Claude native quit component returned no valid status. Check its exit status on your computer.",
"이 종료 작업은 Harness 데스크톱에서만 사용할 수 있습니다.":"This quit action is only available for Harness Desktop.",
"이 Harness 버전에는 검증 가능한 백그라운드 종료 방법이 없습니다. 데스크톱 앱을 업데이트하고 다시 시도하세요.":"This Harness version has no verifiable background quit method. Update the desktop app and try again.",
"실행 중인 Harness 인스턴스의 데이터 디렉터리를 확인할 수 없습니다. 다시 스캔하고 다시 시도하세요.":"The running Harness instance's data directory could not be verified. Scan again and retry.",
