"컴퓨터에서 Claude를 종료합니다. 확인된 정상 종료는 이 시스템에서 지원되지 않습니다.":"Quit Claude on the computer. Confirmed graceful quit is not supported on this system.",
"Claude 종료를 확인하세요.":"Please confirm quitting Claude.",
"클라이언트를 다시 연결하기 전에 비밀번호 보호를 활성화하십시오.":"Enable password protection before reconnecting the client.",
"잘못된 재연결 요청":"Invalid reconnect request",
"Claude 데스크탑 파일 커넥터가 연결 해제되었거나 이 작업을 지원하지 않습니다.":"The Claude Desktop file connector is disconnected or does not support this operation.",
"Claude Desktop 파일 커넥터의 연결이 끊겼습니다. 작업 결과가 확인되지 않았을 수 있습니다.":"The Claude Desktop file connector disconnected; the operation outcome may be uncertain.",
"Claude에는 아직 확인되지 않은 결과가 있는 요청이 있습니다. 컴퓨터에서 결과를 확인하고 새 연결이 필요한 경우 데스크탑 컨트롤을 사용하십시오.":"Claude still has requests with an unconfirmed outcome. Check the results on the computer and use the desktop controls if a new connection is needed.",
"Claude가 다시 연결 중입니다. 잠시 후 다시 시도해 주세요.":"Claude is reconnecting. Please try again shortly.",
"Claude 데스크톱 연결이 응답하지 않습니다. 컴퓨터에서 상태를 확인하고 다시 시도하세요. 클라이언트가 다시 시작되지 않았습니다.":"The Claude desktop connection is not responding. Check its status on the computer and try again. The client was not restarted.",
"화면 보호기가 끝날 때까지 기다리는 중":"Waiting for the screen saver to end",
"잠금 해제를 기다리는 중":"Waiting for unlock",
"데스크탑을 기다리고 있어요":"Waiting for the desktop",
"Mac 화면 보호기가 활성화되었습니다. Claude는 연결을 설정하려면 대화형 데스크탑이 필요하며 화면 보호기가 종료되면 계속됩니다.":"The Mac screen saver is active. Claude needs an interactive desktop to establish the connection and will continue when the screen saver ends.",
"Mac이 잠겨 있습니다. Claude는 연결을 설정하려면 대화형 데스크탑이 필요하며 잠금 해제 후에도 계속됩니다.":"The Mac is locked. Claude needs an interactive desktop to establish the connection and will continue after unlocking.",
"현재 Mac 세션은 대화형이 아닙니다. Claude 연결 설정이 일시 중지되었으며 이 사용자의 데스크톱으로 돌아오면 계속됩니다.":"The current Mac session is not interactive. Claude connection setup is paused and will continue when you return to this user's desktop.",
"휴대전화 페어링":"Pair a phone",
"전화 페어링 QR 코드":"Phone pairing QR code",
"일회용 페어링 링크":"One-use pairing link",
"5분간 유효합니다. 승인하기 전에 여기에서 전화 이름을 확인하세요.":"Valid for 5 minutes. Verify the phone name here before approving.",
"이 컴퓨터 취소":"Revoke this computer",
"페어링된 휴대전화를 모두 취소하시겠습니까? 다시 연결하려면 새 초대가 필요합니다.":"Revoke all paired phones? Reconnecting will require a new invitation.",
"Microsoft Store는 이 장치에 대한 업데이트 자격을 결정합니다. 설치를 위해서는 컴퓨터에 대한 조치가 필요할 수 있습니다.":"Microsoft Store determines update eligibility for this device. Installation may require action on the computer.",
"Microsoft Store 앱 페이지를 요청했습니다. 컴퓨터에서 업데이트를 확인하고 확인하세요.":"Requested the Microsoft Store app page. Check and confirm updates on the computer.",
"시스템 저장소를 열 수 없습니다. 컴퓨터에서 업데이트를 확인하세요.":"Could not open the system store. Check updates on the computer.",

"미리 알림 및 Codex 데스크탑 업데이트":"Reminders and Codex Desktop updates",
