"가입일 7일, 3일, 1일 전에 로그인 기록에 알림":"Notify 7, 3 and 1 days before the subscription date in the login record",
"새로운 Codex 데스크탑 릴리스에 대해 알림":"Notify about new Codex Desktop releases",
"Codex 데스크탑 업데이트":"Codex Desktop updates",
"아직 확인하지 않음":"Not checked yet",
"공식 업데이트 채널 확인 중…":"Checking the official update channel\u2026",
"공식 채널에 새 버전이 게시되었습니다.":"New version published on the official channel",
"이 검사에는 최신 공개 버전이 없습니다.":"No newer public version found in this check",
"컴퓨터에서 확인하세요":"Check on your computer",
"업데이트 확인 실패":"Update check failed",
"네이티브 업데이트 프로그램을 여는 중…":"Opening the native updater\u2026",
"컴퓨터에서 확인을 기다리는 중":"Waiting for confirmation on the computer",
"확인 장소:":"Checked at: ",
"Codex 데스크톱 업데이트 확인":"Check Codex Desktop updates",
"새로운 Codex 버전 확인":"Check for new Codex versions",
"컴퓨터에서 업데이터를 엽니다.":"Open the updater on the computer",
"원격으로 새 버전을 확인할 수 있습니다. 다운로드 및 설치에는 여전히 컴퓨터에서 확인이 필요합니다.":"You can check for new versions remotely. Downloading and installing still require confirmation on the computer.",
"컴퓨터에서 Codex 업데이트를 확인하세요.":"Check for Codex updates on the computer",
"여기에 표시되지 않는 작업을 포함하여 모든 데스크톱 작업이 완료되었는지 확인하고 컴퓨터에서 Codex의 업데이트 확인을 여시겠습니까? Codex는 업데이트 확인, 다운로드 및 설치를 처리합니다.":"Confirm all desktop tasks, including those not visible here, have finished and open Codex’s Check for Updates on the computer? Codex handles checking, downloading and installing the update.",
"이 설치에 대한 업데이트는 컴퓨터나 시스템 저장소에서 확인하세요.":"Check updates on the computer or in its system store for this installation.",
"이 릴리스 채널은 Codex Desktop에서 확인해야 합니다.":"This release channel must be checked by Codex Desktop.",
"네이티브 Codex 업데이트 프로그램은 자격, 단계적 롤아웃 및 업데이트 정책을 결정합니다.":"The native Codex updater determines eligibility, staged rollout and update policy.",
"공식 업데이트 채널을 읽을 수 없습니다. 나중에 다시 시도하거나 컴퓨터에서 확인하세요.":"The official update channel could not be read. Retry later or check on the computer.",
"네이티브 업데이트 프로그램이 열렸습니다. 컴퓨터에 설치를 확인하십시오. 업데이트가 아직 완료되지 않았습니다.":"The native updater has been opened. Confirm installation on the computer; the update is not complete yet.",
"네이티브 업데이트 프로그램을 열 수 없습니다. 컴퓨터를 잠금 해제하고 접근성 권한을 확인하거나 수동으로 확인하세요.":"Could not open the native updater. Unlock the computer and check Accessibility permissions, or check manually.",
"업데이트 프로그램을 열 수 없습니다.":"Could not open the updater",
"시스템 설정 > 개인 정보 보호 및 보안 > 자동화에서 게이트웨이가 시스템 이벤트를 제어하도록 허용한 후 다시 시도하십시오.":"In System Settings > Privacy & Security > Automation, allow the gateway to control System Events, then try again.",
"시스템 설정 > 개인 정보 보호 및 보안 > 접근성에서 게이트웨이를 허용한 후 다시 시도하세요. 이미 활성화된 경우 게이트웨이를 종료했다가 다시 엽니다.":"Allow the gateway in System Settings > Privacy & Security > Accessibility, then try again. If it is already enabled, quit and reopen the gateway.",
"시스템 권한 또는 업데이트 메뉴를 기다리는 동안 시간이 초과되었습니다. 컴퓨터에서 권한 설정을 완료하고 잠금을 해제한 후 다시 시도하세요.":"Timed out waiting for system permission or the update menu. Complete permission setup on the computer, unlock it, then try again.",
"Codex 업데이트 확인 메뉴를 찾을 수 없습니다. Codex 데스크탑에서 업데이트를 수동으로 확인하세요.":"Could not find the Codex Check for Updates menu. Check for updates manually in Codex Desktop.",
"Codex 업데이트 확인 메뉴가 일시적으로 비활성화됩니다. 데스크톱 앱이 준비될 때까지 기다린 후 다시 시도하세요.":"The Codex Check for Updates menu is temporarily disabled. Wait for the desktop app to be ready, then try again.",
"단일 Codex 데스크톱 프로세스를 식별할 수 없습니다. 선택한 데스크톱 앱을 연 다음 다시 시도하세요.":"Could not identify a single Codex Desktop process. Open the selected desktop app, then try again.",
"Codex 업데이트 메뉴를 사용할 수 없습니다. 컴퓨터를 잠금 해제하고 다시 시도하거나 Codex 데스크탑에서 수동으로 업데이트를 확인하세요.":"Could not use the Codex update menu. Unlock the computer and try again, or check for updates manually in Codex Desktop.",
"계정 알림 전송에 실패했습니다. 전화 알림 설정을 확인하세요.":"Account reminder delivery failed. Check phone notification settings.",
"계정 알림을 일시적으로 사용할 수 없으며 다음 확인 시 다시 시도됩니다.":"Account reminders are temporarily unavailable and will retry at the next check.",
"비밀번호 없는 액세스는 데스크탑 업데이트를 제어할 수 없습니다. 컴퓨터를 사용하세요.":"Passwordless access cannot control desktop updates. Use the computer.",
"버전 또는 업데이트 기능이 변경되었습니다. 다시 확인하세요.":"The version or update capability changed. Check again.",

