"보조 채팅 시작":"Start a side chat",
"이 채팅의 맥락을 사용하여 질문을 탐색하세요. 여기서는 기본 채팅의 작업이 계속되지 않습니다.":"Explore a question using this chat’s context. The main chat’s task will not continue here.",
"다양한 기기에서 계속하세요. 채팅을 종료하거나 게이트웨이를 다시 시작하면 내용이 지워집니다.":"Continue across devices. Ending the chat or restarting the gateway clears its contents.",
"보조 채팅은 기본 및 계획 모드를 지원합니다. 후속 작업은 실행 중인 작업 모드를 사용합니다.":"Side chats support Default and Plan modes. Follow-ups use the running task’s mode.",
"후속 작업을 실행 중인 작업이 없습니다. 새 메시지를 보내세요.":"No running task to follow up on. Send a new message.",
"응답을 기다리거나, 메시지를 대기열에 넣거나, 실행 중인 작업에 대한 후속 조치를 취하세요.":"Wait for the reply, queue the message, or follow up on the running task.",
"메시지 큐가 가득 찼습니다. 대기 중인 메시지를 기다리거나 취소합니다.":"The message queue is full. Wait or cancel a queued message.",
"이 메시지는 전송을 시작했거나 이미 처리되었습니다. 상태를 새로 고칩니다.":"This message has started sending or was already handled. Refresh its status.",

"메인채팅":"Main chat",
"분할 창 크기 조정":"Resize split panes",
"여기로 내려오면 오른쪽에 열립니다.":"Drop here to open on the right",
"분할 보기 종료":"Exit split view",
"분할 보기로 열기":"Open in split view",
"잘못된 첨부 파일 목록":"Invalid attachment list",
"이미지 미리보기 닫기":"Close image preview",
"이미지 로드 중…":"Loading image…",
