"구성됨; 이전 비밀번호는 복구할 수 없습니다. 대체하려면 새 비밀번호를 입력하세요.":"Configured; the previous password cannot be recovered. Enter a new password to replace it.",
"고정 도메인 · Cloudflare 터널":"Fixed domain · Cloudflare Tunnel",
"연결 자격 증명이 저장되었습니다.":"Connection credentials saved.",
"저장된 자격 증명을 유지하려면 비워 두세요.":"Leave blank to keep saved credentials",
"자동 재연결을 위해 시스템 자격 증명 저장소에 저장":"Save in the system credential store for automatic reconnection",
"선택 해제하면 새 자격 증명은 이 앱 세션 동안에만 지속됩니다. 이전에 저장된 자격 증명은 아래에서 삭제할 수 있습니다.":"When unchecked, new credentials last for this app session only. Previously saved credentials can be cleared below.",
"연결 자격 증명 저장":"Save connection credentials",
"저장된 자격 증명 지우기":"Clear saved credentials",
"Cloudflare가 준비되었습니다. 임시 HTTPS 주소를 얻으려면 게이트웨이를 저장하고 시작하십시오.":"Cloudflare is ready. Save and start the gateway to get a temporary HTTPS address.",
"이 소스 환경에서는 Cloudflare를 사용할 수 없습니다. 런타임 설정에서 설치하세요.":"Cloudflare is not available in this source environment. Install it in Runtime settings.",
"계정이나 도메인이 필요하지 않습니다. 터널이 다시 생성되면 주소가 변경됩니다. 전화 알림에서 항목 알림을 구성합니다.":"No account or domain needed. The address changes when the tunnel is recreated. Configure entry notifications in Phone notifications.",
"서버 없이 도메인을 사용하세요. Cloudflare 터널을 생성하고 공개 호스트 이름을 구성한 후 여기에 토큰을 입력하세요.":"Use your domain without a server. Create a Cloudflare tunnel and configure its public hostname, then enter its token here.",
"Cloudflare 터널 트래픽은 중국 본토 외부의 서버를 통과할 수 있습니다. 중국 본토에서 직접 액세스하는 경우 속도가 느리거나 시간 초과될 수 있습니다. 안정적인 프록시 경로가 도움이 될 수 있습니다. 실제 성능은 네트워크에 따라 다릅니다.":"Cloudflare Tunnel traffic may pass through servers outside mainland China. Direct access from mainland China may be slow or time out. A reliable proxy route may help; actual performance depends on your network.",
"도메인에 Cloudflare DNS를 사용하세요. 현재 등록자를 유지할 수 있습니다.":"Use Cloudflare DNS for your domain. You can keep your current registrar.",
"터널을 만들고 하위 도메인이 아래의 로컬 게이트웨이 주소를 가리키도록 하세요.":"Create a tunnel and point your subdomain to the local gateway address below.",
"도메인과 터널 토큰을 저장하고 게이트웨이를 시작한 다음 공개 항목을 확인하세요.":"Save the domain and tunnel token, start the gateway, then check the public entry.",
"터널 토큰은 기존 터널을 실행합니다. DNS 레코드를 생성하거나 Cloudflare 계정을 변경하지 않습니다. 이 컴퓨터와 게이트웨이를 온라인 상태로 유지하세요.":"The tunnel token runs an existing tunnel; it does not create DNS records or change your Cloudflare account. Keep this computer and gateway online.",
