"SSH 비밀번호":"SSH password",
"고급 서버 설정":"Advanced server settings",
"SSH 포트는 서버에 연결됩니다. 루프백 포트는 역방향 프록시에서만 사용되며 일반적으로 변경할 필요가 없습니다.":"The SSH port connects to the server. The loopback port is used only by its reverse proxy and usually needs no change.",
"도메인이 아직 확인되지 않았습니다. 먼저 DNS 레코드를 추가하세요.":"The domain does not resolve yet. Add its DNS record first.",
"이 서버를 신뢰하세요":"Trust this server",
"서버 호스트 지문이 변경되었습니다.":"The server host fingerprint has changed",
"이 서버에 대한 첫 번째 연결":"First connection to this server",
"서버 관리자나 서버 콘솔을 통해 이 지문을 확인하세요.":"Verify this fingerprint with your server administrator or server console.",
"호스트 지문이 저장되지 않았습니다.":"Host fingerprint was not saved.",
"Cloudflare 프로그램 및 구성":"Cloudflare program and configuration",
"데스크톱 앱에는 Cloudflare가 포함되어 있습니다. 추가 설치가 필요하지 않습니다. 여기에서 소스 실행 및 사용자 정의 경로를 확인하거나 설치할 수 있습니다.":"The desktop app includes Cloudflare. No extra installation is needed. Source runs and custom paths can be checked or installed here.",
"시스템 자격 증명 저장소에 저장된 연결 자격 증명입니다.":"Connection credentials saved in the system credential store.",
"연결 자격 증명은 이 앱 세션 동안에만 메모리에 보관됩니다.":"Connection credentials are kept in memory for this app session only.",
"먼저 Cloudflare 터널 토큰을 입력하고 저장하세요.":"Enter and save the Cloudflare tunnel token first.",
"먼저 SSH 비밀번호를 입력하고 저장하세요.":"Enter and save the SSH password first.",
"먼저 서버 호스트 지문을 확인하고 확인하세요.":"Check and confirm the server host fingerprint first.",
"서버 지문이 저장된 기록과 다릅니다. 연결이 거부되었습니다.":"The server fingerprint differs from the saved record. Connection refused.",
"SSH 인증에 실패했습니다. 사용자 이름, 비밀번호 또는 개인 키를 확인하세요.":"SSH authentication failed. Check your username, password or private key.",
"SSH 연결에 실패했습니다. 주소, 포트, 키, 네트워크를 확인하세요.":"SSH connection failed. Check the address, port, key and network.",
"Cloudflare 고정 터널 연결 중…":"Connecting the Cloudflare fixed tunnel…",
"고정터널이 연결되었습니다. 도메인이 이 게이트웨이에 도달하는지 확인하세요.":"Fixed tunnel connected. Check that the domain reaches this gateway.",
"고정 터널 연결에 실패했습니다. 토큰, 공개 호스트 이름, 네트워크를 확인하세요.":"Fixed tunnel connection failed. Check the token, public hostname and network.",
"고정 터널이 연결 해제되었습니다. 자동으로 다시 연결됩니다.":"Fixed tunnel disconnected. Reconnecting automatically.",
"고정 터널이 중지됨":"Fixed tunnel stopped",
"SSH의 연결이 끊어졌거나 실패했습니다. 재시도 중입니다. 자격 증명, 호스트 지문 및 루프백 포트를 확인하십시오.":"SSH disconnected or failed. Retrying; check credentials, host fingerprint and loopback port.",
"시스템 자격 증명 저장소를 사용할 수 없습니다. 키체인을 잠금 해제하거나 비밀 서비스를 활성화하세요. 비밀번호는 일반 텍스트로 저장되지 않습니다.":"System credential storage is unavailable. Unlock the keychain or enable Secret Service. Passwords will not be stored as plaintext.",
"연결 자격 증명을 읽을 수 없습니다. 시스템 자격 증명 저장소를 잠금 해제하고 다시 시도하세요.":"Cannot read connection credentials. Unlock the system credential store and retry.",
"연결 자격 증명을 저장할 수 없습니다. 시스템 자격 증명 저장소를 잠금 해제하고 다시 시도하세요.":"Cannot save connection credentials. Unlock the system credential store and retry.",
"게이트웨이 시작 및 진입 알림":"Gateway startup and entry notifications",
"게이트웨이 시작 및 항목 변경 시마다 주소 보내기":"Send addresses on every gateway start and entry change",
"게이트웨이 이름(선택 사항)":"Gateway name (optional)",
"예: 가정용 컴퓨터":"For example: Home computer",
"비밀번호나 로그인 토큰 없이 활성화된 PushPlus, Bark 및 ntfy 채널을 통해 액세스 링크를 보냅니다. 채팅 알림과 무관합니다.":"Send access links through enabled PushPlus, Bark and ntfy channels, without passwords or sign-in tokens. Independent of chat notifications.",
"현재 항목 링크로 테스트 보내기":"Send a test with the current entry link",
"휴대폰 알림을 테스트하기 전에 설정을 저장하고 게이트웨이를 시작하세요. 알림에는 활성화된 LAN 주소, 고정 도메인, 준비된 임시 접속 주소가 포함됩니다. LAN 링크는 같은 네트워크에서 사용할 수 있습니다.":"Save settings and start the gateway before testing phone delivery. Notifications include enabled LAN addresses, fixed domains and ready temporary entries. LAN links require the same network.",
"항목 알림 구성 및 테스트":"Configure and test entry notifications",
"입장 알림이 꺼져 있습니다. 게이트웨이 시작 및 주소 변경 사항은 귀하에게 전송되지 않습니다.":"Entry notifications are off. Gateway starts and address changes will not be sent to you.",
"하나 이상의 알림 채널을 활성화하고 테스트를 보냅니다.":"Enable at least one notification channel and send a test.",
"입장 알림이 켜져 있습니다. 주소는 게이트웨이 시작 시마다 전송되며 항목이 변경되면 업데이트됩니다. 먼저 휴대폰에서 테스트 배송을 확인하세요.":"Entry notifications are on. Addresses are sent on every gateway start, with updates when entries change. Confirm test delivery on your phone first.",
  "컴퓨터의 네트워크가 변경되었습니다. 임시 HTTPS 항목을 다시 작성합니다. 주소가 변경됩니다.":"The computer's network changed; rebuilding the temporary HTTPS entry. Its address will change.",
"일부 항목 알림이 실패하여 다시 시도됩니다.":"Some entry notifications failed and will be retried.",
"입장 알림과 하나 이상의 채널을 활성화한 후 설정을 저장하세요.":"Enable entry notifications and at least one channel, then save settings.",
"게이트웨이를 시작하고 LAN 액세스를 활성화하거나 외부 항목이 준비될 때까지 기다리십시오.":"Start the gateway and enable LAN access or wait for an external entry to be ready.",
"현재 항목을 활성화된 채널로 보냈습니다. 휴대폰으로 영수증을 확인하세요.":"Sent the current entry to enabled channels. Confirm receipt on your phone.",
"게이트웨이 이름에는 최대 80자의 한 줄을 사용하십시오.":"Use a single line of up to 80 characters for the gateway name.",
"Cloudflare 계정이나 도메인이 필요하지 않습니다. 터널이 다시 시작되고 트래픽이 Cloudflare를 통과하면 주소가 변경됩니다. 호스트와 게이트웨이를 온라인 상태로 유지합니다. 원격으로 다시 연결하려면 전화 알림에서 항목 알림을 활성화하고 테스트하세요.":"No Cloudflare account or domain is required. The address changes when the tunnel restarts, and traffic passes through Cloudflare. Keep the host and gateway online. Enable and test entry notifications under Phone notifications to reconnect remotely.",

