  "PushPlus 설정이 저장되었습니다.": "PushPlus settings saved",
  "PushPlus가 테스트 알림을 수락했습니다. 휴대전화를 확인하세요.": "PushPlus accepted the test notification. Check your phone.",
  "PushPlus 웹사이트에서 토큰을 받으세요. 저장한 후 팔로우하려는 각 채팅에서 알림을 활성화하세요.": "Get a token from the PushPlus website. After saving, enable reminders in each chat you want to follow.",
  "먼저 PushPlus, Bark 또는 ntfy를 구성하고 활성화합니다.": "Configure and enable PushPlus, Bark, or ntfy first.",
