  "소스 채팅:": "Source chat: ",
  "귀하의 브라우저가 자동 복사를 차단했습니다. 텍스트를 선택하고 시스템 복사 작업이나 키보드 단축키를 사용합니다.": "Your browser blocked automatic copying. Select the text and use the system Copy action or keyboard shortcut.",
  "이 메시지를 바꾸고 새 응답을 생성하세요. 이전에 실행한 파일 변경 사항과 명령은 그대로 유지됩니다.": "Replace this message and generate a new response. Previously executed file changes and commands will remain.",
  "이번 차례까지 기록을 유지하고 다음 메시지를 기다리세요. 두 채팅 모두 동일한 작업 디렉터리를 공유합니다.": "Keep history through this turn and wait for your next message. Both chats share the same working directory.",
  "원래 채팅을 유지하고 새 분기에서 편집 내용을 사용하여 이번 턴을 다시 생성하세요. 두 채팅 모두 작업 디렉터리를 공유합니다.": "Keep the original chat and regenerate this turn with your edits in a new branch. Both chats share the working directory.",
  "채팅이 바뀌었습니다. 메시지를 다시 선택하세요.": "The chat changed. Select the message again.",
