  "전체 텍스트를 로드할 수 없습니다. 다시 시도해 보세요.": "Could not load the complete text. Try again.",
  "결과는 확인되지 않았습니다. 먼저 채팅 기록을 확인하세요. 다시 제출하면 작업이 반복되지 않습니다.": "The result is not confirmed. Check the chat history first. Submitting again will not repeat the operation.",
  "브랜치가 생성되었으며 채팅 목록에서 사용할 수 있습니다.": "The branch was created and is available in the chat list.",
  "분기가 생성되었지만 편집 내용이 전송되지 않았습니다. 계속하려면 마지막 메시지를 연결하고 편집하세요.": "The branch was created, but your edit was not sent. Connect and edit its last message to continue.",
