  "업데이트 확인에 실패했습니다. 설치가 취소되었습니다.": "Update verification failed. Installation was canceled.",
  "업데이트하기 전에 쓰기 가능한 폴더에 앱을 설치하세요.": "Install the app in a writable folder before updating.",
  "업데이트하기 전에 게이트웨이 데이터 폴더를 앱 설치 외부로 이동하세요.": "Move the gateway data folder outside the app installation before updating.",
  "전체 앱 설치를 찾을 수 없습니다.": "A complete app installation was not found.",
