  "cloudflared 실행 파일": "cloudflared executable",
  "iPhone 또는 Android에 ntfy를 설치하고 동일한 주제를 구독하세요. 그런 다음 휴대폰 채팅에서 알림을 활성화하세요.": "Install ntfy on iPhone or Android and subscribe to the same topic. Then enable reminders in a chat on your phone.",
  "잘못된 ntfy 토큰": "Invalid ntfy token",
  "ntfy 주제에는 1~64자의 문자, 숫자, 밑줄 또는 하이픈이 포함되어야 합니다.": "The ntfy topic must contain 1–64 letters, digits, underscores or hyphens",
  "ntfy 휴대폰 설정 가이드 ↗": "ntfy phone setup guide ↗",
