  "임시 HTTPS": "Temporary HTTPS",
  "채팅 계속하기": "Continue a chat",
  "컴퓨터에서 실행됩니다. · 데스크톱 모델 설정을 사용합니다.": "Runs on your computer · Uses your desktop model settings",
  "사용자": "You",
