  "고급: 대상 위치": "Advanced: target location",
  "터널 또는 역방향 프록시는 다음에서 실행됩니다.": "Tunnel or reverse proxy runs on",
  "이 컴퓨터": "This computer",
  "NAS 또는 다른 장치": "NAS or another device",
  "다른 장치에서 연결할 수 있는 컴퓨터 주소": "Computer address reachable from the other device",
  "LAN 액세스를 활성화하고 게이트웨이 포트를 사용하여 다른 장치에서 연결할 수 있는 컴퓨터 HTTP 주소를 입력합니다.": "Enable LAN access and enter the computer HTTP address reachable from the other device, using the gateway port.",
  "HTTPS 수정 · 서버 설정 필요": "Fixed HTTPS · Server setup required",
  "고정 도메인 · NAS / 역방향 프록시 / Docker": "Fixed domain · NAS / reverse proxy / Docker",
  "고정도메인 · 자체 서버 + SSH": "Fixed domain · Own server + SSH",
  "실행 환경: ": "Running on ",
  "iPhone 또는 Android 휴대폰에 ntfy를 설치하고 잠금 화면을 포함한 알림을 허용하세요.": "Install ntfy on your iPhone or Android phone and allow notifications, including on the lock screen.",
  "이 컴퓨터에서 실행 중": "Running on this computer",
  "데스크톱 앱에 저장된 프로젝트에 빈 채팅을 만든 다음 휴대폰에서 메시지를 보내세요. 컴퓨터에서 이 채팅이 열립니다.": "Create an empty chat in a project saved in the desktop App, then send messages from your phone. The computer will open this chat.",
  "알림에 채팅 제목 포함": "Include chat titles in notifications",
  "사용할 수 없는 주소입니다": "This address is not available",
  "IPv6 영역 식별자는 지원되지 않습니다.": "IPv6 zone identifiers are not supported",
  "주소에는 공백이 포함될 수 없습니다.": "Addresses cannot contain whitespace",
  "잘못된 주소 포트": "Invalid address port",
  "게이트웨이 포트를 사용하여 NAS에서 연결할 수 있는 컴퓨터의 HTTP 주소를 입력합니다. LAN 액세스를 활성화합니다. 네트워크가 서로 연결할 수 없는 경우 먼저 경로를 설정하거나 SSH 서버 연결을 사용하십시오.": "Enter the computer's HTTP address as reachable from the NAS, using the gateway port. Enable LAN access. If the networks cannot reach each other, establish a route first or use an SSH server connection.",
