  "확인 대기 중": "Pending confirmation",
  "보류 중인 확인에 대한 알림": "Notifications for pending confirmations",
  "수동으로 입력한 클릭 URL가 우선순위를 갖습니다. 고정 도메인을 자동으로 팔로우하려면 비워두세요. 채팅 제목과 내용은 기본적으로 제외됩니다. 이전 알림에 만료된 임시 링크가 있을 수 있습니다. 자체 호스팅 ntfy는 즉각적인 iPhone 알림을 위해 APN 업스트림이 필요합니다.": "A manually entered click URL takes priority. Leave it empty to follow a fixed domain automatically. Chat titles and content are excluded by default. Old notifications may have expired temporary links. Self-hosted ntfy needs an APNs upstream for instant iPhone notifications.",
