  "서버가 알림을 수락했지만 전화기가 무음 상태인 경우 ntfy 구독, OS 알림 권한 및 집중 모드를 확인하세요. Android에서는 즉시 전달 및 백그라운드 활동을 허용합니다. 자체 호스팅 ntfy는 즉각적인 iPhone 알림을 위해 APN 업스트림이 필요합니다.": "If the server accepted the notification but the phone stays silent, check the ntfy subscription, OS notification permissions and Focus mode. On Android, allow instant delivery and background activity. Self-hosted ntfy needs an APNs upstream for instant iPhone notifications.",
