  "로그인 인증": "Login authentication",
  "청취 포트": "Listening port",
  "이 디렉터리에는 게이트웨이 설정, 알림 토큰, 로그인 자격 증명 및 로그가 저장됩니다.": "This directory stores gateway settings, notification tokens, login credentials and logs.",
  "사용 중인 포트": "Port in use",
  "다른 게이트웨이가 이 포트를 사용하고 있습니다. 런타임 설정을 확인하세요.": "Another gateway is using this port. Check Runtime settings.",
  "항구가 점유되었습니다. 기존 게이트웨이를 확인하세요. 포트는 자동으로 변경되지 않습니다": "The port is occupied. Check the existing gateway; the port will not be changed automatically",
