  "게이트웨이 시작 시간이 초과되었습니다. 런타임 로그를 확인하세요.": "Gateway startup timed out. Check the runtime logs.",
  "게이트웨이가 중지되었습니다. 지금 ntfy 배송을 테스트할 수 있습니다. 채팅 알림을 실행하려면 게이트웨이가 필요합니다.": "The gateway is stopped. You can test ntfy delivery now; chat reminders require a running gateway.",
  "게이트웨이 중지됨": "Gateway stopped",
  "게이트웨이가 실행 중입니다.": "Gateway is running.",
  "게이트웨이가 준비되었습니다. 전화 채팅에서 알림을 열고 채팅 알림을 활성화한 후 저장하세요.": "Gateway ready. Open Reminders in a phone chat, enable chat reminders and save.",
  "게이트웨이가 중지되었습니다. 먼저 설정을 저장하고 ZIP 배포를 내보낼 수 있습니다.": "Gateway stopped. You can save settings and export a deployment ZIP first.",
  "게이트웨이가 실행 중입니다. 확인을 클릭하여 수정된 항목을 확인합니다.": "Gateway running. Click Check to verify the fixed entry.",
  "게이트웨이가 실행 중입니다. 연결을 추가하거나 변경하기 전에 개요에서 중지한 다음 저장하고 다시 시작하세요.": "The gateway is running. Stop it in Overview before adding or changing connections, then save and restart.",
  "게이트웨이 런타임 로그": "Gateway runtime logs",
  "네트워크 및 로그인": "Network and login",
  "네트워크 설정이나 프로그램 경로를 변경하기 전에 게이트웨이를 중지하십시오. 모델, 제공자 및 기술은 원래 Codex 채팅을 따릅니다.": "Stop the gateway before changing network settings or program paths. Model, provider and Skills follow the original Codex chat.",
