  "HTTPS 주소를 변경하기 전에 게이트웨이를 중지한 다음 저장하고 다시 시작하세요.": "Stop the gateway before changing HTTPS addresses, then save and restart",
  "현재 연결이 끊어지지 않도록 네트워크 설정이나 런타임 경로를 변경하기 전에 게이트웨이를 중지하세요.": "Stop the gateway before changing network settings or runtime paths to avoid losing your current connection",
