  "먼저 데스크탑 런처에서 ntfy를 구성하고 활성화하십시오.": "Configure and enable ntfy in the desktop launcher first",
  "cloudflared 실행 파일을 선택하거나 임시 외부 액세스를 끄십시오.": "Select the cloudflared executable or turn off temporary external access",
