  "채팅 기록을 확인하세요. 게이트웨이는 이 메시지를 자동으로 다시 보내지 않습니다.": "Check the chat history. The gateway will not resend this message automatically.",
  "요청 실패": "Request failed",
  "질문 도구를 사용하여 ”계속 테스트” 또는 ”테스트 완료”를 선택한 다음 답변을 기다립니다. 명령을 실행하거나 파일을 변경하지 마십시오.": "Use the question tool to let me choose “Continue testing” or “Finish testing”, then wait for my reply. Do not run commands or change files.",
  "자격 증명, 쿼리 매개변수 또는 조각 없이 완전한 HTTP/HTTPS URL를 입력하세요.": "Enter a complete HTTP/HTTPS URL without credentials, query parameters or fragments",
