  "잘못된 경로 형식": "Invalid path format",
  "답장을 입력하세요": "Enter your reply",
  "API 서비스에서 지원하는 모델 ID를 입력하세요.": "Enter a model ID supported by your API service",
  "실행 중": "Running",
  "런타임 로그": "Runtime logs",
  "런타임 설정": "Runtime settings",
  "채팅으로 돌아가기": "Back to chats",
  "게이트웨이의 주소 허용 목록입니다. HTTPS 역방향 프록시 또는 터널이 https://codex.try2love.com.와 같이 다른 곳에 이미 구성되어 있는 추가 도메인에만 사용하십시오. URL를 추가해도 터널이 생성되지 않고, DNS를 구성하거나 인증서가 요청되지 않습니다. 프록시는 도메인의 호스트 헤더를 보존해야 합니다. 연결 카드의 고정 도메인은 자동으로 추가됩니다. LAN 또는 임시 Cloudflare 액세스만 사용하려면 이 항목을 비워 두세요.": "This is the gateway's address allowlist. Use it only for extra domains whose HTTPS reverse proxy or tunnel is already configured elsewhere, such as https://codex.try2love.com. Adding a URL does not create a tunnel, configure DNS or request a certificate; the proxy must preserve the domain's Host header. Fixed domains in the connection cards are added automatically. Leave this empty for LAN or temporary Cloudflare access alone.",
  "개요": "Overview",
  "연결 중": "Connecting",
  "Codex에 연결하세요": "Connect to your Codex",
  "연결 이름": "Connection name",
  "연결 이름은 최대 100자까지 포함할 수 있습니다.": "Connection names can contain up to 100 characters",
  "사이": "Connections",
  "데스크톱에 연결 중": "Connecting to desktop",
  "컴퓨터 연결": "Connect computer",
  "잘못된 연결 유형 또는 스위치": "Invalid connection type or switch",
