  "추가 권한이 필요할 때 물어보세요.": "Ask you when extra permissions are needed.",
  "Codex는 추가 권한이 필요한 작업을 검토합니다.": "Codex reviews actions that need extra permissions.",
  "개별 승인 없이 작업 공간 및 네트워크 외부의 파일에 대한 액세스를 허용합니다.": "Allow access to files outside the workspace and the network without individual approval.",
  "이 채팅에 컴퓨터 파일 및 네트워크에 대한 전체 액세스를 허용하시겠습니까? 신뢰하는 작업에 대해서만 활성화하세요.": "Allow this chat full access to computer files and the network? Enable only for tasks you trust.",
  "읽기 권한 옵션…":"Reading permission options…",
  "권한 기능을 확인할 수 없습니다. 데스크탑 설정을 확인한 후 이 패널을 다시 여십시오.":"Permission capabilities could not be confirmed. Check desktop settings, then reopen this panel.",
  "CLI 권한 기능을 확인할 수 없습니다. CLI 런타임 및 정책을 확인한 후 새로 고치세요.":"CLI permission capabilities could not be confirmed. Check the CLI runtime and policy, then refresh.",
  "이 작업 공간 또는 관리자 정책은 이 권한 모드를 허용하지 않습니다.":"This workspace or administrator policy does not allow this permission mode.",
  "Codex 데스크탑 설정에서 전체 액세스 옵션을 활성화한 다음 이 패널을 다시 엽니다.":"Enable the Full access option in Codex desktop settings, then reopen this panel.",
  "승인 가능 여부가 확인되지 않았습니다. 먼저 데스크탑에서 이 모드를 선택한 다음 이 패널을 다시 엽니다.":"Approve for me availability is unconfirmed. Select this mode on the desktop first, then reopen this panel.",
  "현재 Codex 런타임 또는 구성에서는 승인이 비활성화되어 있습니다.":"Approve for me is disabled in the current Codex runtime or configuration.",
  "이 권한 프로필을 사용할 수 없습니다. 데스크탑에서 Codex를 확인하거나 업데이트하세요.":"This permission profile is unavailable. Check or update Codex on your desktop.",
  "이 권한 프로필은 CLI 런타임에서는 사용할 수 없습니다. Codex CLI를 업데이트한 후 새로고침하세요.":"This permission profile is unavailable in the CLI runtime. Update Codex CLI, then refresh.",
