  "앱 제어": "App control",
  "채팅 읽기 시간이 초과되었습니다.": "Reading the chat timed out",
  "Codex 데스크톱 작업 상태를 확인할 수 없습니다. 데스크톱 앱을 확인하고 다시 시도하세요.": "Cannot confirm Codex desktop task status. Check the desktop app and try again.",
  "Codex에는 실행 중인 작업이나 보류 중인 확인이 있습니다. 닫기 전에 완료하세요.": "Codex has running tasks or pending confirmations. Finish them before closing.",
  "Codex에 작업 또는 확인되지 않은 작업이 있습니다. 닫기 전에 문제를 해결하세요.": "Codex has tasks or unconfirmed operations. Resolve them before closing.",
  "Codex 데스크톱 및 SSH 채팅을 읽을 수 없습니다. 연결을 확인하고 다시 시도하십시오.": "Cannot read Codex desktop and SSH chats. Check the connections and try again.",
  "구성된 데스크톱 앱을 찾을 수 없습니다. 다시 스캔하세요.": "Configured desktop app not found. Scan again.",
  "데스크톱 앱 또는 해당 데이터 디렉터리를 사용할 수 없습니다. 다시 스캔하세요.": "The desktop app or its data directory is unavailable. Scan again.",
  "앱 프로세스가 변경되어 작업 상태를 확인할 수 없습니다. 닫기 전에 다시 확인하세요.": "The app processes changed, so task status cannot be confirmed. Check again before closing.",
  "모든 앱 작업이 종료되었는지 확인할 수 없습니다. 컴퓨터를 확인하고 다시 시도하세요.": "Cannot confirm that all app tasks have ended. Check on your computer and try again.",
  "작업이 실행 중이거나 확인 대기 중입니다. 앱을 닫거나 다시 시작하기 전에 완료하세요.": "Tasks are running or awaiting confirmation. Finish them before closing or restarting the app.",
  "앱이 시작되지 않았습니다. 컴퓨터를 확인하고 다시 시도하세요.": "The app has not started. Check on your computer and try again.",
  "앱이 구성되었으며 열 준비가 되었습니다.": "App configured and ready to open",
  "여러 Harness 백그라운드 인스턴스가 감지되었습니다. 다시 시도하기 전에 컴퓨터의 추가 인스턴스를 닫으십시오. 모든 작업 상태를 확인할 수 있는 것은 아닙니다.": "Multiple Harness background instances were detected. Close the extra instances on your computer before trying again; not all task states can be confirmed.",
  "이 Harness 커넥터 버전은 작업 상태를 확인할 수 없습니다. 컴퓨터에서 Harness를 종료한 후 다시 연결하세요.": "This Harness connector version cannot verify task status. Quit Harness on your computer, then reconnect.",
  "앱을 여는 중…": "Opening app…",
